// Obtenemos el texto de salida del nodo de Perplexity
const inputText = items[0].json.choices?.[0]?.message?.content || "";

// Expresión regular flexible para capturar las tres tendencias
// Soporta saltos de línea y espacios variables
const regex = /-?\s*Tendencia_1:\s*(.*?)\s*-?\s*Tendencia_2:\s*(.*?)\s*-?\s*Tendencia_3:\s*(.*)/s;

const match = inputText.match(regex);

if (!match) {
  // En caso de error, devolvemos el contenido original para depurar
  return [
    {
      json: {
        error: "No se encontraron las tres tendencias en el formato esperado.",
        contenido_original: inputText
      }
    }
  ];
}

// Devolvemos un solo ítem con tres campos
return [
  {
    json: {
      "Tendencia 1": match[1].trim(),
      "Tendencia 2": match[2].trim(),
      "Tendencia 3": match[3].trim()
    }
  }
];

