parameters.jsCode:
/**
 * n8n Function node: Parse salida Perplexity (con división de resumen > 4000 chars)
 * Lee la salida del nodo Perplexity con estructura:
 * [
 *   {
 *     "id": "...",
 *     "citations": [...],
 *     "message": "{...JSON...}"
 *   }
 * ]
 */

function limpiarTexto(texto) {
  return texto
    .replace(/^```(?:json)?/gi, "")
    .replace(/```$/g, "")
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/,\s*([}\]])/g, "$1")
    .trim();
}

function mdToHtml(md) {
  if (!md) return "";
  let html = md.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
  html = html.replace(/(?:^|\n)- (.*)/g, "<li>$1</li>");
  html = html.replace(/(<li>[\s\S]*?<\/li>)/g, "<ul>$1</ul>");
  html = html.replace(/\n{2,}/g, "</p><p>");
  html = `<p>${html}</p>`;
  html = html.replace(/<p>\s*(<ul>[\s\S]*?<\/ul>)\s*<\/p>/g, "$1");
  return html;
}

/**
 * Divide un texto largo en partes de <= maxChars buscando cortes naturales.
 * Prioriza saltos de párrafo o secciones (“**” o "\n\n").
 */
function dividirTexto(texto, maxChars = 4000) {
  if (texto.length <= maxChars) return [texto];

  const partes = [];
  let resto = texto;

  while (resto.length > maxChars) {
    // Busca un punto lógico de corte antes del límite
    let corte = resto.lastIndexOf("\n\n", maxChars);
    if (corte === -1) corte = resto.lastIndexOf("**", maxChars);
    if (corte === -1) corte = resto.lastIndexOf(". ", maxChars);
    if (corte === -1) corte = maxChars; // último recurso

    const parte = resto.slice(0, corte).trim();
    partes.push(parte);
    resto = resto.slice(corte).trim();
  }

  if (resto.length > 0) partes.push(resto);
  return partes;
}

// --- PARSEO PRINCIPAL ---
const entrada = items[0].json;
if (!entrada.message) throw new Error("No se encontró el campo 'message' en la entrada del nodo.");

let data;
try {
  data = JSON.parse(entrada.message);
} catch {
  const limpio = limpiarTexto(entrada.message);
  data = JSON.parse(limpio);
}

// Validar campos clave
const campos = ["resumenExtendido", "pregunta1", "pregunta2", "pregunta3", "pregunta4", "pregunta5", "fuentes"];
for (const c of campos) {
  if (!(c in data)) throw new Error(`Falta el campo obligatorio: ${c}`);
}

// --- Convertir markdown a HTML ---
const resumenExtendido = data.resumenExtendido.trim();
const resumenHTML = mdToHtml(resumenExtendido);

// --- Dividir resumen si excede 4000 caracteres ---
const partesResumen = dividirTexto(resumenExtendido, 4000);

// --- Normalizar fuentes ---
const fuentesNormalizadas = (data.fuentes || []).map(f => ({
  titulo: f.titulo?.trim() || "",
  url: f.url?.trim() || "",
  fecha: f.fecha?.trim() || "",
}));

// --- Estructura final ---
const salida = {
  resumenExtendidoParte1: partesResumen[0] || "",
  resumenExtendidoParte2: partesResumen[1] || "",
  resumenExtendidoCompleto: resumenExtendido,
  resumenHTML,
  preguntas: [
    data.pregunta1.trim(),
    data.pregunta2.trim(),
    data.pregunta3.trim(),
    data.pregunta4.trim(),
    data.pregunta5.trim()
  ],
  fuentes: fuentesNormalizadas,
  fechaCorteInvestigacion: data.fechaCorteInvestigacion || null,
  notaDeCobertura: data.notaDeCobertura || "",
  citations: entrada.citations || [],
  caracteresTotales: resumenExtendido.length,
  partes: partesResumen.length
};

// --- Salida ---
return [{ json: salida }];

