    --body-font: 'Helvetica', 'Arial', sans-serif;
  }

  body {
    font-family: var(--body-font);
    background-color: var(--creamy-bg);
    margin: 0;
    padding: 2rem; /* Espacio para que el contenedor respire */
    line-height: 1.7;
    color: var(--dark-text);
  }

  .container {
    max-width: 800px;
    margin: 0 auto;
    background-color: var(--warm-container);
    border-radius: 8px;
    box-shadow: 0 10px 30px rgba(74, 59, 42, 0.1);
    overflow: hidden;
  }

  /* --- INICIO DE MODIFICACIÓN CSS --- */
  .main-image {
    max-width: 640px;   /* Máximo 640px (tamaño nuevo) */
    width: 100%;        /* Responsiva, se encoge si es necesario */
    height: auto;
    display: block;
    margin: 2rem auto 2.5rem auto; /* Centrada y con espacio vertical */
    border-radius: 8px; /* Consistente con el contenedor */
  }
  /* --- FIN DE MODIFICACIÓN CSS --- */

  .article-content {
    /* La imagen ahora va dentro de este article, pero el padding es correcto */
    padding: 1.5rem 3rem 3rem 3rem;
  }

  h1, h2, h3 {
    font-family: var(--header-font);
    margin-top: 1.5em;
